def cal_sum(n):
    if n <= 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 2

    # Perrin sequence: P(0)=3, P(1)=0, P(2)=2
    # P(n) = P(n-2) + P(n-1)
    p0, p1 = 3, 0
    p2 = 2
    total = 0

    # Sum the Perrin numbers from P(0) to P(n)
    for i in range(n + 1):
        if i == 0:
            total += p0
        elif i == 1:
            total += p1
        elif i == 2:
            total += p2
        else:
            p_next = p0 + p1
            total += p_next
            p0, p1 = p1, p_next

    return total
```

