def is_samepatterns(patterns1, patterns2):
    if len(patterns1) != len(patterns2):
        return False

    pattern_map = {}
    pattern_reverse = {}

    for i in range(len(patterns1)):
        p1 = patterns1[i]
        p2 = patterns2[i]

        # Check if p1 already has a mapping
        if p1 in pattern_map:
            if pattern_map[p1] != p2:
                return False
        else:
            pattern_map[p1] = p2

        # Check if p2 already has a mapping
        if p2 in pattern_reverse:
            if pattern_reverse[p2] != p1:
                return False
        else:
            pattern_reverse[p2] = p1

    return True
```

