def start_withp(words):
    result = []
    for word in words:
        if word.startswith('P') or word.startswith('p'):
            # Split the string by space and take the first word
            parts = word.split()
            if parts:
                first_word = parts[0]
                if first_word.startswith('P') or first_word.startswith('p'):
                    result.append(first_word)
    return tuple(result[:2])
```

